}
.settings-modal .voice-model-state[data-state="error"] {
  color: var(--red);
}
.settings-modal .voice-model-row.voice-model-attention {
  outline: 2px solid color-mix(in srgb, var(--accent) 68%, transparent);
  outline-offset: -2px;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 12%, transparent);
}
.settings-modal .voice-model-actions,
.settings-modal .voice-connection-actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.settings-modal .voice-model-actions .import-btn {
  margin: 0;
}
.settings-modal .voice-model-progress {
  max-width: 430px;
  padding-top: 9px;
}
.settings-modal .voice-model-progress-track {
  height: 6px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--bg-secondary);
}
.settings-modal .voice-model-progress-track > span {
  display: block;
  width: 0;
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
  transition: width .2s ease;
}
.settings-modal .voice-model-progress-track.indeterminate > span {
  width: 35%;
  animation: voice-progress-sweep 1.2s ease-in-out infinite;
}
.settings-modal .voice-model-progress-track.complete > span {
  width: 100%;
  animation: none;
}
@keyframes voice-progress-sweep {
  0% { transform: translateX(-120%); }
  50% { transform: translateX(90%); }
  100% { transform: translateX(285%); }
}
.settings-modal .voice-model-progress small,
.settings-modal .voice-model-footnote {
  color: var(--text-muted);
  font-size: 9.5px;
  line-height: 1.5;
}
.settings-modal .voice-model-progress small {
  display: block;
  margin-top: 5px;
}
.settings-modal .voice-model-footnote {
  padding: 10px 0 0;
}
.settings-modal .voice-connection-card {
  min-width: 0;
}
.settings-modal .voice-connection-card summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0;
  color: var(--text-primary);
  cursor: pointer;
}
.settings-modal .voice-connection-card summary > span {
  min-width: 0;
}
.settings-modal .voice-connection-card summary strong {
  font-size: 12px;
}
.settings-modal .voice-connection-card summary em {
  flex: 0 0 auto;
  color: var(--text-muted);
  font-size: 9px;
  font-style: normal;
}
.settings-modal .voice-connection-body {
  display: grid;
  gap: 12px;
  padding: 14px 0 2px 18px;
}
.settings-modal .voice-cloud-disclosure {
  margin: 0;
  color: var(--text-muted);
  font-size: 10px;
  line-height: 1.5;
}
.settings-modal .voice-test-status {
  min-height: 14px;
  color: var(--green);
  font-size: 10px;
}
.settings-modal .voice-test-status.error {
  color: var(--red);
}
.kb-modal.settings-modal {
  max-width: 780px;
}

/* API key and provider settings */
.api-key-input {
  width: 100%; padding: 10px 12px; border-radius: 6px;
  border: 1px solid var(--border); background: var(--bg-primary);
  color: var(--text-primary); font-size: 13px; font-family: monospace;
  margin-top: 8px; color-scheme: dark;
}
[data-theme="light"] .api-key-input { color-scheme: light; }
.api-key-input:focus { border-color: var(--accent); }
.api-key-status { font-size: 13px; margin-bottom: 4px; }
.api-key-notice {
  font-size: 11px; color: var(--text-muted); margin-top: 12px;
  padding: 10px; background: var(--bg-card); border-radius: var(--radius-sm);
  border: 1px solid var(--border); line-height: 1.5;
}
.ai-provider-toggle {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 4px;
}
.ai-provider-btn {
  min-width: 0; padding: 6px 8px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 12px;
  cursor: pointer; font-weight: 500; transition: all 0.15s; font-family: inherit;
  display: inline-flex; align-items: center; justify-content: center; gap: 4px; white-space: nowrap;
  flex: 1 1 auto;
}
@media (max-width: 480px) {
  .ai-provider-btn { padding: 5px 10px; font-size: 12px; gap: 3px; }
  .ai-provider-logo { width: 12px; height: 12px; }
}
.ai-provider-logo { width: 14px; height: 14px; flex-shrink: 0; }
.ai-provider-btn.active { background: var(--accent); color: white; border-color: var(--accent); }
.ai-provider-btn:hover:not(.active) { background: var(--bg-hover); }
.ai-provider-panel { margin-top: 12px; }
.ai-provider-desc {
  font-size: 12px; color: var(--text-muted); line-height: 1.5; margin-bottom: 10px;
}
.ai-model-tip {
  font-size: 12px; line-height: 1.5; color: var(--text-secondary);
  border-left: 3px solid var(--accent); padding: 8px 12px; margin-bottom: 12px;
  background: var(--bg-hover); border-radius: 0 4px 4px 0;
}
.or-oauth-btn {
  width: 100%; padding: 10px 16px; border: none; border-radius: var(--radius);
  background: var(--accent-gradient); color: white; font-weight: 600; font-size: 14px;
  font-family: inherit; cursor: pointer; transition: all 0.2s;
}
.or-oauth-btn:hover { transform: translateY(-1px); box-shadow: var(--shadow-glow); }
.or-oauth-divider {
  display: flex; align-items: center; gap: 12px; margin: 12px 0;
}
.or-oauth-divider::before, .or-oauth-divider::after {
  content: ''; flex: 1; height: 1px; background: var(--border);
}
.or-oauth-divider span {
  font-size: 11px; color: var(--text-muted); white-space: nowrap;
}

/* Local AI settings in Settings modal */
.local-ai-settings { margin-top: 4px; }
.local-ai-status {
  display: flex; align-items: center; gap: 8px; font-size: 13px;
}
.local-ai-status-dot {
  width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted);
  flex-shrink: 0;
}
.local-ai-status-dot.connected { background: var(--green); box-shadow: 0 0 6px rgba(34,197,94,0.5); }
.local-ai-status-dot.disconnected { background: var(--red); }

/* Model Advisor */
.model-advisor { margin-top: 12px; border: 1px solid var(--border); border-radius: var(--radius-sm); overflow: hidden; }
.model-advisor-hw {
  padding: 10px 12px; background: var(--bg-hover);
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  font-size: 12px; color: var(--text-secondary);
}
.model-advisor-hw-chip { display: flex; align-items: center; gap: 4px; white-space: nowrap; }
.model-advisor-row {
  display: grid; grid-template-columns: auto 1fr auto auto auto;
  gap: 8px; align-items: center;
  padding: 7px 12px; border-top: 1px solid var(--border);
  font-size: 12px;
}
.model-advisor-row:hover { background: var(--bg-hover); }
.model-advisor-row.active { background: rgba(99,102,241,0.06); }
.model-advisor-badge { font-size: 13px; flex-shrink: 0; line-height: 1; }
.model-advisor-name { font-weight: 500; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.model-advisor-size { color: var(--text-muted); white-space: nowrap; }
.model-advisor-verdict { white-space: nowrap; font-size: 11px; }
.model-advisor-verdict.fits { color: var(--green); }
.model-advisor-verdict.tight { color: var(--yellow); }
.model-advisor-verdict.toobig { color: var(--red); }
.model-advisor-verdict.unknown { color: var(--text-muted); }
.model-advisor-verdict.cloud { color: var(--accent); }
.model-advisor-fitness { white-space: nowrap; font-size: 11px; color: var(--text-muted); }
.model-advisor-fitness.fitness-great { color: var(--green); font-weight: 600; }
.model-advisor-fitness.fitness-good { color: var(--accent); }
.model-advisor-fitness.fitness-fair { color: var(--yellow); }
.model-advisor-fitness.fitness-poor { color: var(--red); }
.model-advisor-suggest { padding: 10px 12px; border-top: 1px solid var(--border); }
.model-advisor-suggest-title {
  font-size: 11px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.06em; color: var(--text-muted); margin-bottom: 8px;
}
.model-advisor-pull-row { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; }
.model-advisor-pull-cmd {
  font-family: var(--font-mono); font-size: 12px;
  background: var(--bg-primary); padding: 4px 8px;
  border-radius: 4px; border: 1px solid var(--border);
  color: var(--text-secondary); flex: 1;
}
.model-advisor-pull-why { font-size: 11px; color: var(--text-muted); margin-bottom: 8px; }
.model-advisor-override { padding: 8px 12px; border-top: 1px solid var(--border); }
.model-advisor-override-toggle {
  font-size: 11px; color: var(--text-muted); cursor: pointer;
  display: flex; align-items: center; gap: 5px; user-select: none;
}
.model-advisor-override-toggle:hover { color: var(--text-secondary); }
.model-advisor-override-body {
  margin-top: 6px; display: flex; align-items: center; gap: 8px;
}
.model-advisor-override-body input {
  width: 72px; padding: 4px 8px; font-size: 12px;
  background: var(--bg-primary); border: 1px solid var(--border);
  border-radius: 4px; color: var(--text-primary);
}

/* Imported data entries */
.imported-entry {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; align-items: center;
  padding: 10px 16px; background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-sm); margin-bottom: 6px; font-size: 13px;
}
.imported-entry .ie-info { min-width: 0; color: var(--text-secondary); }
.imported-entry .ie-mainline { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.imported-entry .ie-meta { display: flex; align-items: center; gap: 8px; min-width: 0; margin-top: 3px; color: var(--text-muted); font-size: 11px; line-height: 1.35; }
.imported-entry .ie-file,
.imported-entry .ie-model { min-width: 0; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.imported-entry .ie-file { max-width: min(320px, 45vw); }
.imported-entry .ie-model { max-width: min(260px, 35vw); }
.imported-entry .ie-type { flex: 0 0 auto; font-size: 10px; letter-spacing: 0.04em; text-transform: uppercase; }
.imported-entry .ie-date { color: var(--text-primary); font-weight: 500; }
.imported-entry .ie-count { flex: 0 0 auto; color: var(--text-muted); }
.imported-entry .ie-actions { display: flex; align-items: center; gap: 4px; justify-content: flex-end; }
.imported-entry .ie-remove,
.imported-entry .ie-edit {
  background: none; border: none; color: var(--text-muted); cursor: pointer;
  font-size: 12px; padding: 4px 10px; border-radius: 4px; transition: all 0.15s; font-family: inherit;
}
.imported-entry .ie-remove:hover { color: var(--red); background: var(--red-bg); }
.imported-entry .ie-edit:hover { color: var(--text-primary); background: var(--bg-hover); }
@media (max-width: 640px) {
  .imported-entry { grid-template-columns: 1fr; align-items: stretch; padding: 12px; }
  .imported-entry .ie-meta { flex-wrap: wrap; }
  .imported-entry .ie-file,
  .imported-entry .ie-model { max-width: 100%; }
  .imported-entry .ie-actions { justify-content: flex-start; flex-wrap: wrap; }
}

/* Settings sections */
.settings-section { margin-top: 16px; }
.settings-label { font-size: 13px; font-weight: 600; display: block; margin-bottom: 8px; color: var(--text-secondary); }
.settings-group-title {
  font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--text-muted); margin-top: 24px; padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}

/* Settings tabs */
.settings-tabs-bar {
  display: flex; gap: 2px; margin: 16px 0 0;
  border-bottom: 1px solid var(--border);
  position: sticky; top: -32px; z-index: 2;
  background: var(--bg-secondary); padding-top: 4px;
}
.settings-tab-btn {
  position: relative; padding: 10px 18px; border: none; background: none;
  color: var(--text-muted); font-size: 13px; font-weight: 500;
  font-family: var(--font-display); cursor: pointer;
  transition: color 0.2s; white-space: nowrap;
  display: inline-flex; align-items: center; gap: 6px;
}
.settings-tab-btn::after {
  content: ''; position: absolute; bottom: -1px; left: 8px; right: 8px;
  height: 2px; border-radius: 2px 2px 0 0; background: transparent;
  transition: background 0.2s, box-shadow 0.2s;
}
.settings-tab-btn:hover { color: var(--text-secondary); }
.settings-tab-btn.active { color: var(--accent); font-weight: 600; }
.settings-tab-btn.active::after {
  background: var(--accent);
  box-shadow: 0 0 8px color-mix(in srgb, var(--accent) 30%, transparent);
}
.settings-tab-btn svg { width: 14px; height: 14px; flex-shrink: 0; opacity: 0.6; }
.settings-tab-btn.active svg { opacity: 1; }
.settings-tab-panel { display: none; padding-top: 6px; }
.settings-tab-panel.active {
  display: block;
  animation: settingsTabFadeIn 0.2s ease;
}
@keyframes settingsTabFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
.settings-tab-panel .settings-section:first-child { margin-top: 8px; }
.settings-tab-panel .settings-group-title:first-child { margin-top: 12px; }
.settings-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.settings-row .settings-section { margin-top: 8px; }
.settings-links-row { display: flex; flex-wrap: wrap; gap: 8px 16px; margin-top: 8px; }
.settings-link-btn {
  background: none; border: none; color: var(--text-muted); font-size: 13px;
  font-family: inherit; cursor: pointer; padding: 4px 0; text-decoration: none;
  transition: color 0.15s;
}
.settings-link-btn:hover { color: var(--text-primary); text-decoration: underline; }

/* Theme picker */
.settings-theme-toggle { display: flex; align-items: center; gap: 4px; }
.settings-theme-btn {
  padding: 4px 12px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 12px;
  cursor: pointer; font-weight: 500; transition: all 0.15s; font-family: inherit;
}
.settings-theme-btn.active { background: var(--accent); color: white; border-color: var(--accent); }
.settings-theme-btn:hover:not(.active) { background: var(--bg-hover); }
.settings-theme-swatch {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  flex-shrink: 0;
  border: 1px solid rgba(255,255,255,0.06);
}
.settings-theme-swatch-dark { background: linear-gradient(135deg, #222635 0%, #4f8cff 100%); }
.settings-theme-swatch-light { background: linear-gradient(135deg, #f5f6fa 0%, #3b7cf5 100%); }
.settings-theme-swatch-cyberterm { background: linear-gradient(135deg, #0b0d0b 0%, #4ade80 100%); border-radius: 0; }
.settings-theme-swatch-glass { background: linear-gradient(135deg, #c986ff 0%, #6ec4ff 100%); border-radius: 12px; }
.settings-theme-swatch-synth-sunrise { background: linear-gradient(135deg, #ff7a18 0%, #ff2bd6 50%, #7c3aed 100%); border-radius: 2px; }
.settings-theme-swatch-neuromancer { background: linear-gradient(135deg, #00e5ff 0%, #ff2bd6 100%); border-radius: 0; }

/* Privacy status card and collapsible configure */
.settings-modal .settings-privacy-section {
  padding-top: 2px;
}
.privacy-overview-row {
  align-items: flex-start;
  margin-bottom: 12px;
}
.privacy-overview-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--border));
  border-radius: var(--radius-sm);
  background: var(--accent-fill);
  font-size: 15px;
  line-height: 1;
  flex: 0 0 auto;
}
.privacy-status-card {
  display: flex; align-items: flex-start; gap: 10px;
  padding: 10px 14px; border-radius: var(--radius-sm);
  margin-bottom: 8px; line-height: 1.4;
}
.privacy-status-icon { font-size: 18px; flex-shrink: 0; margin-top: 1px; }
.privacy-status-body { flex: 1; min-width: 0; }
.privacy-status-title { font-size: 13px; font-weight: 600; }
.privacy-status-detail { font-size: 12px; color: var(--text-muted); margin-top: 2px; }
.privacy-status-enhanced {
  background: color-mix(in srgb, var(--green) 8%, transparent); border: 1px solid color-mix(in srgb, var(--green) 25%, transparent);
}
.privacy-status-enhanced .privacy-status-title { color: var(--green); }
.privacy-status-basic {
  background: color-mix(in srgb, var(--yellow) 8%, transparent); border: 1px solid color-mix(in srgb, var(--yellow) 25%, transparent);
}
.privacy-status-basic .privacy-status-title { color: var(--yellow); }
.privacy-configure-toggle {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; color: var(--text-muted); cursor: pointer;
  margin-top: 12px; padding: 4px 0; user-select: none;
}
.privacy-configure-toggle:hover { color: var(--text-secondary); }
.privacy-configure-arrow { font-size: 9px; transition: transform 0.15s; }
.privacy-configure-body { padding-top: 8px; }
.privacy-setting-row {
  padding-top: 12px;
  margin-top: 12px;
  border-top: 1px solid var(--border);
}
.privacy-setting-row + .privacy-setting-row {
  margin-top: 12px;
}
.privacy-setting-note {
  margin-top: 5px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.35;
}

/* Pending-tombstone confirm UI in Settings Sync. */
.sync-tombstone-banner {
  margin-bottom: 16px; padding: 12px 14px;
  border: 1px solid var(--yellow); background: color-mix(in srgb, var(--yellow) 8%, transparent);
  border-radius: 6px; font-size: 12px;
}
.sync-tombstone-head { margin-bottom: 8px; line-height: 1.45; }
.sync-tombstone-head strong { color: var(--yellow); }
.sync-tombstone-help { display: block; color: var(--text-muted); font-size: 11px; margin-top: 2px; }
.sync-tombstone-row {
  display: flex; align-items: center; gap: 8px; padding: 6px 0;
  border-top: 1px solid color-mix(in srgb, var(--yellow) 18%, transparent);
}
.sync-tombstone-name { flex: 1; font-weight: 500; color: var(--text-primary); }
.sync-tombstone-meta { font-size: 11px; color: var(--text-muted); }
.sync-tombstone-btn {
  font-size: 11px; padding: 4px 10px; border-radius: 4px; cursor: pointer;
  border: 1px solid var(--border); background: var(--bg-secondary); color: var(--text-primary);
}
.sync-tombstone-apply { background: var(--red); color: #fff; border-color: var(--red); }
.sync-tombstone-reject { background: var(--green); color: #fff; border-color: var(--green); }

/* Cross-device Sync owns its controls here. Do not rely on the chat panel's
   lazy stylesheet: Settings can open before Chat, which previously left the
   hidden checkbox with an invisible, zero-size slider. */
.sync-settings-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
}
.sync-settings-state {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
}
.sync-settings-badge {
  padding: 2px 7px;
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.sync-settings-badge.is-enabled {
  border-color: color-mix(in srgb, var(--green) 45%, var(--border));
  background: color-mix(in srgb, var(--green) 10%, transparent);
  color: var(--green);
}
.sync-settings-badge.is-paused {
  border-color: color-mix(in srgb, #f59e0b 45%, var(--border));
  background: color-mix(in srgb, #f59e0b 10%, transparent);
  color: #f59e0b;
}
label.sync-settings-toggle {
  display: inline-flex;
  align-items: center;
  min-width: 32px;
  min-height: 28px;
  cursor: pointer;
}
label.sync-settings-toggle input { display: none; }
label.sync-settings-toggle .sync-settings-toggle-slider {
  position: relative;
  display: block;
  width: 32px;
  height: 18px;
  border-radius: 999px;
  background: var(--border);
  transition: background .2s ease;
}
label.sync-settings-toggle .sync-settings-toggle-slider::before {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--bg-primary);
  transition: transform .2s ease;
}
label.sync-settings-toggle input:checked + .sync-settings-toggle-slider { background: var(--accent); }
label.sync-settings-toggle input:checked + .sync-settings-toggle-slider::before { transform: translateX(14px); }
label.sync-settings-toggle input:disabled + .sync-settings-toggle-slider { opacity: .45; cursor: not-allowed; }
.sync-setup-actions,
.sync-management-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 14px;
}
.sync-setup-actions .import-btn,
.sync-management-actions .import-btn {
  width: 100%;
  min-height: 36px;
  padding: 7px 12px;
  font-size: 12px;
}
.sync-disable-btn {
  border-color: color-mix(in srgb, var(--red) 55%, var(--border));
  color: var(--red);
}
.sync-setup-restore-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: stretch;
  gap: 8px;
}
.sync-setup-restore-actions .import-btn,
.sync-setup-restore-actions .confirm-btn {
  min-height: 38px;
  white-space: nowrap;
}
.sync-setup-restore-cancel { min-width: 76px; }
.sync-management-help {
  margin-top: 6px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.45;
}

/* Sync identity comparison card — intentionally more prominent than the
   recovery phrase so device mismatches can be spotted without exposing it. */
.sync-identity-card {
  margin-bottom: 16px;
  padding: 12px;
  background: var(--accent-fill);
  border: 1px solid var(--ref-border);
